+  const worker = new Worker(new URL(import.meta.url));
+  worker.on('error', (err) => { assert.fail(err); });
+  worker.on('message', mustCall(async (message) => {
+    assert.strictEqual(message, 'ready');
+    assert.strictEqual(await worker.terminate(), 1);
+  }));
+}

